input.new_string:
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const quotePremium = (items: Item[]): number => {
  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  return policyBase * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): Result[] => {
  return scenario.steps.map((step) => ({
    premium: quotePremium((step as { items: Item[] }).items),
  }));
};

