export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const quotePremium = (items: Item[]): number => {
  const basePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

