const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

/** Items that share the same `type`, and so are priced together. */
type AlikeItems = { type: string; items: Item[] };

const groupByType = (items: Item[]): AlikeItems[] => {
  const itemsByType = new Map<string, Item[]>();
  for (const item of items) {
    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
  }
  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
};

const formsBlock = ({ items }: AlikeItems): boolean => items.length === BLOCK_SIZE;

const basePremiumFor = (alike: AlikeItems): number =>
  formsBlock(alike) ? BLOCK_PREMIUM : alike.items.length * BASE_PREMIUMS[alike.type];

const totalBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);

const quotePremium = (items: Item[]): number => {
  const base = totalBasePremium(items);
  // Keep the surcharge additive (base + base * rate). The algebraically
  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
  // which Math.ceil turns into a premium that is 1 G too high.
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): Result[] =>
  scenario.steps.map((step) => {
    if (step.op === "quote") return { premium: quotePremium(step.items) };
    throw new Error(`Unsupported step: ${step.op}`);
  });

