import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums: single main items (plus 5 G fee, 10 % first insurance) ---
  it("quotes an empty item list as 5 G (only the processing fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(results).toEqual([{ premium: 5 }]);
  });
  it("quotes a plain sword (base 100 G) as 115 G (100 + 10 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
      ],
    });

    expect(results).toEqual([{ premium: 115 }]);
  });
  it("quotes a plain amulet (base 60 G) as 71 G (60 + 6 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
      ],
    });

    expect(results).toEqual([{ premium: 71 }]);
  });
  it("quotes a plain staff (base 80 G) as 93 G (80 + 8 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }] },
      ],
    });

    expect(results).toEqual([{ premium: 93 }]);
  });
  it("quotes a plain potion (base 40 G) as 49 G (40 + 4 first insurance + 5 fee)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(results).toEqual([{ premium: 49 }]);
  });

  // --- Components and the building block of 3 alike ---
  it("quotes 1 rune at base premium 25 G", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    // base 25 + 2.5 first insurance + 5 fee = 32.5 → 33 (rounded up)
    expect(results).toEqual([{ premium: 33 }]);
  });
  it("quotes 2 runes at base premium 50 G", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    // base 50 + 5 first insurance + 5 fee = 60
    expect(results).toEqual([{ premium: 60 }]);
  });
  it("quotes 3 runes at base premium 60 G (block applies)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    // block base 60 + 6 first insurance + 5 fee = 71
    expect(results).toEqual([{ premium: 71 }]);
  });
  it("quotes 4 runes at base premium 100 G (no block — block requires exactly 3)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    // base 100 + 10 first insurance + 5 fee = 115
    expect(results).toEqual([{ premium: 115 }]);
  });
  it("quotes 7 runes at base premium 175 G", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
    });

    // base 175 + 17.5 first insurance + 5 fee = 197.5 → 198 (rounded up)
    expect(results).toEqual([{ premium: 198 }]);
  });
  it("quotes 2 runes + 1 moonstone at base premium 75 G (no block: different types)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    // base 75 + 7.5 first insurance + 5 fee = 87.5 → 88 (rounded up)
    expect(results).toEqual([{ premium: 88 }]);
  });
  it("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            ...Array.from({ length: 3 }, () => ({ type: "rune" })),
            ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
          ],
        },
      ],
    });

    // two blocks: 60 + 60 = 120 + 12 first insurance + 5 fee = 137
    expect(results).toEqual([{ premium: 137 }]);
  });

  // --- Item-specific modifiers ---
  it("adds a 50 % curse surcharge to the cursed item's base premium", () => {
    const results = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }] },
      ],
    });

    // base 100 + 50 curse + 10 first insurance (10 % of base) + 5 fee = 165
    expect(results).toEqual([{ premium: 165 }]);
  });
  it.todo("adds a 30 % surcharge for a sword with exactly enchantment 5");
  it.todo("adds no high-enchantment surcharge for a sword with enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first insurance surcharge per item in a quote");
  it.todo("applies a 15 % follow-up discount on the customer's second contract");
  it.todo("applies the first insurance surcharge on a follow-up contract too");

  // --- Modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy — cursed sword + plain amulet: base 160 G, +50 G curse");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) at 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) at 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("pays 400 G for a regular sword (steel, enchantment 3) damaged 500 G (damage minus 100 G deductible)");
  it.todo("pays 100 G for a rune damaged 200 G (no enchantment or material, so no special clause)");

  // --- Claims: special clauses ---
  it.todo("pays 400 G for a dragon-material sword with exactly enchantment 8 damaged 1000 G (50 % clause, then deductible)");
  it.todo("pays 400 G for a dragon-material sword, enchantment 9, damaged 1000 G (50 % rule wins over full reimbursement)");
  it.todo("pays 700 G for a dragon-material sword, enchantment 5, damaged 800 G (full reimbursement, then deductible)");
  it.todo("pays 400 G for a steel sword, enchantment 9, damaged 1000 G (50 % clause, then deductible)");

  // --- Deductible per damage event ---
  it.todo("pays 600 G when a dragon attack damages a sword (500 G) and an amulet (300 G) — 100 G deductible per damaged item");

  // --- Insurance sum and cap ---
  it.todo("reports a remaining cap of 3200 G minus the payout for a policy covering a sword and an amulet (insurance sum 1600 G)");
  it.todo("caps a cursed sword policy at 2000 G based on the unmodified insurance value");
  it.todo("caps a policy covering a sword and 3 runes at 3500 G (insurance sum 1750 G — the block discount affects the premium only)");
  it.todo("caps two swords at 4000 G (insurance sum 2000 G)");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("exhausts the cap across successive claims — sword (cap 2000 G), two claims of 1500 G: payout 1400 G (600 G left), then 600 G (0 G left)");

  // --- Errors: non-zero exit and stderr ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");
  it.todo("rejects a claim whose damage references an item not covered by the policy (amulet damaged when only a sword is insured)");
  it.todo("rejects a claim whose damage references an unknown item type");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("rejects a claim containing a damage entry with a negative amount");

  // --- CLI ---
  it.todo("returns one result per step, in order, for the schema example scenario");
});

