  // Keep the surcharge additive (base + base * rate). The algebraically
  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
  // which Math.ceil turns into a premium that is 1 G too high.
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(
    base + totalCurseSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): Result[] =>
  scenario.steps.map((step) => {
    if (step.op === "quote") return { premium: quotePremium(step.items) };
    throw new Error(`Unsupported step: ${step.op}`);
  });

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

/** Items that share the same `type`, and so are priced together. */
type AlikeItems = { type: string; items: Item[] };

const groupByType = (items: Item[]): AlikeItems[] => {
  const itemsByType = new Map<string, Item[]>();
  for (const item of items) {
    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
  }
  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
};

const formsBlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const basePremiumFor = ({ items }: AlikeItems): number =>
  formsBlock(items)
    ? BLOCK_PREMIUM
    : items.reduce((total, item) => total + itemBasePremium(item), 0);

const totalBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);

/**
 * Sums `rate` × base premium over the items that `applies` to. Item-specific
 * surcharges are charged on the item's own base premium, never on the policy's,
 * so each one is an independent additive term.
 */
const perItemSurcharge = (
  items: Item[],
  applies: (item: Item) => boolean,
  rate: number,
): number =>
  items
    .filter(applies)
    .reduce((total, item) => total + itemBasePremium(item) * rate, 0);

const isCursed = (item: Item): boolean => item.cursed === true;

const totalCurseSurcharge = (items: Item[]): number =>
  perItemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const totalHighEnchantmentSurcharge = (items: Item[]): number =>
  perItemSurcharge(items, isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_RATE);

const quotePremium = (items: Item[]): number => {
  const base = totalBasePremium(items);
  // Keep the surcharge additive (base + base * rate). The algebraically
  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
  // which Math.ceil turns into a premium that is 1 G too high.
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(
    base + totalCurseSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): Result[] =>
  scenario.steps.map((step) => {
    if (step.op === "quote") return { premium: quotePremium(step.items) };
    throw new Error(`Unsupported step: ${step.op}`);
  });

