const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

/**
 * An item-specific surcharge: `rate` × the item's own base premium, charged
 * once per item the rule `applies` to. Never charged on the policy's base, so
 * every rule contributes an independent additive term.
 */
type ItemSurcharge = { applies: (item: Item) => boolean; rate: number };

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
];

const itemSurchargesFor = (item: Item): number =>
  ITEM_SURCHARGES.filter(({ applies }) => applies(item)).reduce(
    (total, { rate }) => total + itemBasePremium(item) * rate,
    0,
  );

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurchargesFor(item), 0);

/**
 * A policy-wide modifier: `rate` × the policy's base premium, charged once per
 * quote. Like the item surcharges, each rule contributes an independent
 * additive term rather than compounding on earlier ones.
 */
const firstInsuranceSurcharge = (base: number): number =>
  base * FIRST_INSURANCE_SURCHARGE_RATE;

const quotePremium = (items: Item[]): number => {
  const base = totalBasePremium(items);
  // Every term is added to `base`, never multiplied onto a running total. The
  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
  // base 100, which Math.ceil turns into a premium that is 1 G too high.
  return Math.ceil(
    base + totalItemSurcharges(items) + firstInsuranceSurcharge(base) + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): Result[] =>
  scenario.steps.map((step) => {
    if (step.op === "quote") return { premium: quotePremium(step.items) };
    throw new Error(`Unsupported step: ${step.op}`);
  });

