const insuranceSum = (items: Item[]): number =>
  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);

/**
 * The reimbursable value of a damage before the deductible. Special clauses key
 * off the DAMAGED ITEM's own properties (material, enchantment), so this takes
 * the insured item rather than the damage entry alone. No clause exists yet, so
 * the reimbursed amount is currently the full damage.
 */
const reimbursedAmount = (damage: Damage, _damagedItem: Item): number => damage.amount;

/** The deductible is charged per damaged item, not once per incident. */
const damagePayout = (damage: Damage, damagedItem: Item): number =>
  reimbursedAmount(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;

const incidentPayout = (damages: Damage[], insured: Item[]): number =>
  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
  // than to each damage, so a single incident loses at most 1 G to rounding.
  Math.floor(
    damages.reduce((total, damage) => total + damagePayout(damage, damagedItem(insured, damage)), 0),
  );

/** A policy pays out at most twice the insurance sum of the items it covers. */
const payoutCap = (items: Item[]): number =>
  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;

const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
  const insured = insuredItems(steps, policyIndex);
  const payout = incidentPayout(damages, insured);
  return { payout, remainingCap: payoutCap(insured) - payout };
};

export const runScenario = (scenario: Scenario): Result[] =>
  scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const policy = {
        customer: scenario.customer,
        priorContracts: priorContractsAt(scenario.steps, stepIndex),
      };
      return { premium: quotePremium(step.items, policy) };
    }
    return claimResult(scenario.steps, step.policy, step.incident.damages);
  });

