import { readFileSync } from "node:fs";
import { runScenario, type Scenario } from "./claim-office.js";

const readStdin = (): string => readFileSync(0, "utf8");

const main = (): void => {
  const scenario = JSON.parse(readStdin()) as Scenario;
  process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
};

try {
  main();
} catch (error) {
  // Every rejection the MHPCO makes surfaces here as a non-zero exit: the
  // library states the reason by throwing, and the CLI is what turns that into
  // an exit code the caller can act on.
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exit(1);
}

